Here is the Semgrep YAML rule:

```yaml
id: vuln-htmlunit-940dc7fd
languages:
  - java
message: Uncontrolled resource consumption in getNextElementUpwards method
severity: ERROR
pattern-sources:
  - patterns:
    - pattern-either:
      - pattern-inside: |
          function($startingNode) {
            $parent = $startingNode->getParentNode();
            if ($parent == null || $parent == $startingNode->this) {
              return null;
            }
            $next = $parent->getNextSibling();
            while ($next != null && !$this->isAccepted($next)) {
              $next = $next->getNextSibling();
            }
            if ($next == null) {
              return $this->getNextElementUpwards($parent);
            }
            return $next;
          }
        pattern-not-inside: |
          function($startingNode) {
            $parent = $startingNode->getParentNode();
            while ($parent != null && $parent != $startingNode->this) {
              $next = $parent->getNextSibling();
              while ($next != null && !$this->isAccepted($next)) {
                $next = $next->getNextSibling();
              }
              if ($next != null) {
                return $next;
              }
              $parent = $parent->getParentNode();
            }
            return null;
          }
```

This rule will detect the vulnerable behavior of the `getNextElementUpwards` method in the `DomNode` class. It will not match the patched behavior of the method. The pattern-sources field is used to specify the patterns to be searched for in the codebase. The pattern-either field is used to specify that the pattern should be present in either the code or the patched code. The pattern-not-inside field is used to specify that the pattern should not be present in the patched code.

